qss:
/* ===== PS01-FLUENT 结构观感（v3.42.0，随深浅主题）===== */
/* 胶囊控件：右端视图状态区（专注/打字机/分段钮）Win11 圆润造型 */
#vsz QToolButton {
  border-radius: 13px;
  padding: 3px 9px;
}
#vsz QToolButton:checked {
  background: {accent_soft};
  color: {accent};
}
/* 控件大圆角 6px */
QToolButton, QMenu, QLineEdit, QPushButton {
  border-radius: 6px;
}
QMenuBar::item {
  border-radius: 6px;
}
QMenu {
  border-radius: 8px;
}
QMenu::item:selected {
  background: {menu_hover_bg};
  color: {menu_sel_text};
}

editor_css:
/* 编辑区 = 浮于云母之上的白色圆角卡片 */
body { background: {mica} !important; }
#editor {
  max-width: 980px;
  margin: 8px auto 0 auto;
  background: {card};
  border-radius: 8px 0 0 0;
  box-shadow: 0 0 0 1px {border};
  box-sizing: border-box;
  min-height: calc(100vh - 8px);
}

#editor { max-width: 980px; margin: 0 auto; padding: 30px 110px 45vh 110px; }

